# state derived fields
needle="s['open_count'] = len(_state['open']); s['leverage'] = LEVERAGE;"
s=s.replace(needle, "s['open_count'] = len(_state['open']); s['max_positions'] = MAX_POSITIONS; s['leverage'] = LEVERAGE; s['trading_budget'] = round(min(s.get('trading_budget', s['balance']), s['balance']), 6); s['reserved_margin'] = round(sum(float(x.get('margin_required',0)) for x in _state['open']), 6); s['available_margin_budget'] = round(max(0.0, s['trading_budget'] - s['reserved_margin']), 6); s['mode'] = MODE;")
# Add demo account helpers before paper_state
idx=s.index('\ndef paper_state():')
